#include "dual_checkpoint_probe.cuh"
#include "dual_model_bundle.hpp"
#include "pilot_reader.hpp"
#include <random>
#include <cstdio>
int main(){try{using namespace tao::dual;std::ifstream f("build/pilot_train.bin",std::ios::binary);auto docs=tao::data::read_pilot(f);auto t=docs.at(0);t.pop_back();Config c;c.layers=1;c.d=4;c.s=2;c.m=3;c.e=8;c.vocab=261;CpuModel init(c);std::mt19937 rng(8191);std::normal_distribution<float>d(0,.12f);for(auto&kv:init.w)for(float&v:kv.second)v=kv.first.find("norm")!=std::string::npos?1.f:d(rng);GpuTrainer tr(init);size_t positions=0,supervised=0,chunks=0;double loss=0;for(size_t begin=1;begin<t.size()&&chunks<2;begin+=16){size_t n=0;for(size_t i=begin;i<t.size()&&i<begin+16;++i){auto y=tr.graph.step(t[i-1].id);loss+=seed_loss(y,t[i].id,t[i].loss);n+=t[i].loss;++positions;}if(n){tr.graph.tape.backward();++chunks;}tr.detach();supervised+=n;if(positions>4096)throw std::runtime_error("pilot context budget");}if(chunks!=2||!supervised)throw std::runtime_error("insufficient supervised blocks");tr.update(supervised);save_probe(tr,"build/pilot_gpu_step.dcp");auto cpu=effective_cpu(tr);std::string fingerprint(64,'0');save_bundle(cpu,"build/pilot_gpu_step.dsb",fingerprint);auto loaded=load_bundle("build/pilot_gpu_step.dsb",fingerprint);if(loaded.w!=cpu.w)throw std::runtime_error("bundle weights");auto state=loaded.initial();unsigned token=256;printf("cpu_greedy_ids=");for(int i=0;i<8;++i){auto logits=loaded.step(token,state);for(unsigned blocked:{256u,257u,258u})logits[blocked]=-INFINITY;token=unsigned(std::max_element(logits.begin(),logits.end())-logits.begin());printf("%u,",token);if(token==259||token==260){loaded.step(token,state);break;}}printf("\nPASS real_data GPU positions=%zu supervised=%zu steps=%u loss_before_update=%.7f\n",positions,supervised,tr.steps,loss/supervised);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
